    /**check leave color */
    checkLeaveTypes(id, color) {
        var valid = true;
        for (let obj of this.leavesTypeData) {
            if (obj.id !== id && obj.leavecolor === color) {
                if (obj.id == id && obj.leavecolor === color) {
                    this.isLeaveColorAlreadyExists = false;
                }
                else {
                    this.isLeaveColorAlreadyExists = true;
                }
                // valid =false;
                valid = true;
                return valid;
            }
            else {
                // this.isLeaveColorAlreadyExists = true;
                this.isLeaveColorAlreadyExists = false;
            }
        }
        return valid;
    }
